from review_bindings import default_help
SHORTCUTS['marker']='Add a bookmark at the playhead, or edit the bookmark already there. Click to jump to it; double-click to edit its name, note and color. Drag to move it. Alt-drag a point left or right to extend it into a span, then drag the ends to resize without Alt. Bookmarks are above In/Out selections and always accept left clicks. The same bookmarks, including their spans, export with your clips or optionally onto the editor timeline.'
SHORTCUTS['trim_file']='Open the clip trimming functionality. This shows lossless cut points and preserves editor selections. This action may share a shortcut with Confirm Trim: outside Trim it opens the page; once in Trim, the same shortcut confirms the plan.'
SHORTCUTS['create_trim']='Verify the current file-trim plan, then review the replacement / copy. This action may share a shortcut with Trim file mode; it runs only when already on the Trim page.'
for _action,_text in list(SHORTCUTS.items()):
    SHORTCUTS[_action]=_text.rsplit('\n\nDefault: Primary ',1)[0]+'\n\n'+default_help(_action)


def wording(text):
    if not isinstance(text,str):return text
    if text in REPLACEMENTS:return REPLACEMENTS[text].replace('Default: Resolve;','Default: DaVinci Resolve;')
    body,separator,binding=text.rpartition('\n\nShortcut: ')
    if separator and body in REPLACEMENTS:return REPLACEMENTS[body]+separator+binding
    return text
